<?php
require_once __DIR__ . '/auth.php';
function page_top(string $title): void {
  $u=current_user(); $base=app_base();
  echo '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0b1f3a"><title>'.h($title).' | KMO</title><style>';
  echo ':root{--navy:#0b1f3a;--navy2:#12345b;--gold:#d6a63c;--bg:#f4f7fb;--card:#fff;--text:#172033;--muted:#667085;--line:#e4e8ef;--danger:#b42318;--ok:#067647}*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui,Arial;background:var(--bg);color:var(--text)}header{background:linear-gradient(135deg,var(--navy),var(--navy2));color:white}.head{max-width:1200px;margin:auto;padding:16px;display:flex;justify-content:space-between;gap:16px;align-items:center}.brand{font-weight:900;font-size:20px}.user{font-size:12px;color:#dbe6f3;text-align:right}nav{background:#fff;border-bottom:1px solid var(--line)}nav .nav{max-width:1200px;margin:auto;padding:0 12px;display:flex;gap:4px;overflow:auto}nav a{display:block;padding:13px 12px;color:var(--navy);text-decoration:none;font-weight:700;font-size:14px;white-space:nowrap}nav a:hover{background:#f1f5f9}main{max-width:1200px;margin:20px auto;padding:0 14px 40px}.grid{display:grid;gap:15px}.g2{grid-template-columns:repeat(2,minmax(0,1fr))}.g3{grid-template-columns:repeat(3,minmax(0,1fr))}.g4{grid-template-columns:repeat(4,minmax(0,1fr))}.card{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:17px;box-shadow:0 5px 18px #1018280a}.card h2,.card h3{margin:0 0 8px}.muted{color:var(--muted);font-size:13px}.metric{font-size:26px;font-weight:900}.green{color:var(--ok)}.red{color:var(--danger)}label{display:block;font-size:12px;font-weight:800;margin:9px 0 5px}input,select,textarea{width:100%;padding:11px;border:1px solid #cfd6e2;border-radius:10px;background:white;color:var(--text);font-size:14px}textarea{min-height:80px;resize:vertical}.btn,button{display:inline-block;border:0;border-radius:10px;padding:11px 14px;background:var(--navy);color:white;font-weight:800;text-decoration:none;cursor:pointer}.btn.gold,button.gold{background:var(--gold);color:#202635}.btn.light,button.light{background:#eef2f7;color:var(--navy)}.btn.danger,button.danger{background:#fee4e2;color:#b42318}.actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}.tablewrap{overflow:auto;border:1px solid var(--line);border-radius:12px}table{width:100%;border-collapse:collapse;min-width:760px}th,td{padding:10px;border-bottom:1px solid var(--line);font-size:13px;text-align:left}th{background:#f8fafc;position:sticky;top:0}.badge{display:inline-block;padding:4px 8px;border-radius:999px;background:#eef2f7;font-size:11px;font-weight:800}.badge.in{background:#ecfdf3;color:#067647}.badge.out{background:#fff1f2;color:#b42318}.flash{padding:11px 13px;border-radius:10px;margin-bottom:12px;background:#ecfdf3;color:#067647}.error{padding:11px 13px;border-radius:10px;margin-bottom:12px;background:#fff1f2;color:#b42318}.section-title{display:flex;justify-content:space-between;align-items:end;gap:10px;margin:22px 0 10px}.section-title h2{margin:0}.hide{display:none}@media(max-width:800px){.g2,.g3,.g4{grid-template-columns:1fr}.head{align-items:flex-start}.metric{font-size:22px}}@media print{header,nav,.no-print,.actions,form{display:none!important}body{background:white}main{max-width:none;margin:0;padding:0}.card{box-shadow:none;break-inside:avoid}}';
  echo '</style></head><body><header><div class="head"><div><div class="brand">KMO Gestão</div><div style="font-size:12px;color:#dbe6f3">Área Segura • Financeiro</div></div><div class="user">'.h($u['name']??'').' <br>'.h($u['role']??'').'</div></div></header><nav><div class="nav"><a href="'.$base.'/prestacao.php">Prestação de Contas</a><a href="'.$base.'/calculadora.php">Calculadora de Desconto</a>';
  if(($u['role']??'')==='admin') echo '<a href="'.$base.'/usuarios.php">Usuários</a>';
  echo '<a href="'.$base.'/logout.php">Sair</a></div></nav><main>';
}
function page_bottom(): void { echo '</main></body></html>'; }
